17	class Bzip2ReadBuffer::Bzip2StateWrapper
18	{
19	public:
20	    Bzip2StateWrapper()
21	    {
22	        memset(&stream, 0, sizeof(stream));
23	
24	        int ret = BZ2_bzDecompressInit(&stream, 0, 0);
25	
26	        if (ret != BZ_OK)
27	            throw Exception(
28	                ErrorCodes::BZIP2_STREAM_DECODER_FAILED,
29	                "bzip2 stream encoder init failed: error code: {}",
30	                ret);
31	    }
32	
33	    ~Bzip2StateWrapper()
34	    {
35	        BZ2_bzDecompressEnd(&stream);
36	    }
37	
38	    bz_stream stream;
39	};
40	
41	Bzip2ReadBuffer::Bzip2ReadBuffer(std::unique_ptr<ReadBuffer> in_, size_t buf_size, char *existing_memory, size_t alignment)
42	    : CompressedReadBufferWrapper(std::move(in_), buf_size, existing_memory, alignment)
43	    , bz(std::make_unique<Bzip2StateWrapper>())
44	    , eof_flag(false)
45	{
46	}
47	
48	Bzip2ReadBuffer::~Bzip2ReadBuffer() = default;
49	
50	bool Bzip2ReadBuffer::nextImpl()
51	{
52	    if (eof_flag)
53	        return false;
54	
55	    int ret;
56	    do
57	    {
58	        if (!bz->stream.avail_in)
59	        {
60	            in->nextIfAtEnd();
61	            bz->stream.avail_in = in->buffer().end() - in->position();
62	            bz->stream.next_in = in->position();
63	        }
64	
65	        bz->stream.avail_out = internal_buffer.size();
66	        bz->stream.next_out = internal_buffer.begin();
67	
68	        ret = BZ2_bzDecompress(&bz->stream);
69	
70	        in->position() = in->buffer().end() - bz->stream.avail_in;
71	    }
72	    while (bz->stream.avail_out == internal_buffer.size() && ret == BZ_OK && !in->eof());
73	
74	    working_buffer.resize(internal_buffer.size() - bz->stream.avail_out);
75	
76	    if (ret == BZ_STREAM_END)
77	    {
78	        if (in->eof())
79	        {
80	            eof_flag = true;
81	            return !working_buffer.empty();
82	        }
83	        else
84	        {
85	            throw Exception(
86	                ErrorCodes::BZIP2_STREAM_DECODER_FAILED,
87	                "bzip2 decoder finished, but input stream has not exceeded: error code: {}", ret);
88	        }
89	    }
90	
91	    if (ret != BZ_OK)
92	        throw Exception(
93	            ErrorCodes::BZIP2_STREAM_DECODER_FAILED,
94	            "bzip2 stream decoder failed: error code: {}",
95	            ret);
96	
97	    if (in->eof())
98	    {
99	        eof_flag = true;
100	        throw Exception(ErrorCodes::UNEXPECTED_END_OF_FILE, "Unexpected end of bzip2 archive");
101	    }
102	
103	    return true;
104	}
105	}
